*** Begin Patch
*** Update File: src/lib.rs
@@
-pub fn capped(value: u8, _limit: u8) -> u8 { value }
+pub fn capped(value: u8, _limit: u8) -> u8 { value }
+
+#[cfg(test)]
+mod tests {
+    use super::capped;
+
+    #[test]
+    fn retains_values_below_the_limit() {
+        assert_eq!(capped(4, 7), 4);
+    }
+
+    #[test]
+    fn retains_values_equal_to_the_limit() {
+        assert_eq!(capped(7, 7), 7);
+    }
+
+    #[test]
+    fn caps_values_above_the_limit() {
+        assert_eq!(capped(9, 7), 7);
+    }
+}
*** End Patch
